{
  "name": "Smart Shopping Calculator",
  "description": "A Telegram Mini App for calculating discounts, unit prices, and promo deals."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppView {
  MAIN_MENU = 'MAIN_MENU',
  DISCOUNT_CALC = 'DISCOUNT_CALC',
  PROMO_CALC = 'PROMO_CALC',
  UNIT_PRICE_CALC = 'UNIT_PRICE_CALC',
  REVERSE_CALC = 'REVERSE_CALC',
  PRO_MODE = 'PRO_MODE',
  SETTINGS = 'SETTINGS',
}

export interface MenuItem {
  id: AppView;
  title: string;
  icon: React.ReactNode;
  color: string;
}

export interface SettingsState {
  currency: string;
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '',
  ...props 
}) => {
  const baseStyle = "px-4 py-3 rounded-xl font-medium transition-all duration-200 active:scale-95 disabled:opacity-50 disabled:active:scale-100 flex items-center justify-center gap-2";

  const variants = {
    primary: "bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-slate-700 hover:bg-slate-600 text-white border border-slate-600",
    danger: "bg-red-600 hover:bg-red-500 text-white",
  };

  return (
    <button 
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React from 'react';

interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
  suffix?: string;
}

export const Input: React.FC<InputProps> = ({ label, suffix, className = '', ...props }) => {
  return (
    <div className={`flex flex-col gap-1.5 ${className}`}>
      <label className="text-sm text-slate-400 font-medium ml-1">
        {label}
      </label>
      <div className="relative">
        <input 
          className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all placeholder-slate-500"
          {...props}
        />
        {suffix && (
          <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none">
            {suffix}
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeShoppingDeal = async (userQuery: string, currency: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Ошибка: API ключ не найден. Пожалуйста, настройте environment variable.";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are a helpful shopping assistant calculator. 
      The user will ask a question about shopping, prices, or comparing deals.
      The currency is ${currency}.

      User Query: "${userQuery}"

      Please provide a concise analysis.
      1. If it's a comparison, do the math step-by-step but keep it brief.
      2. State clearly which option is better.
      3. Format the final answer nicely with bold text for the winner.
      4. Answer in Russian language.`,
      config: {
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });

    return response.text || "Не удалось получить ответ от помощника.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Произошла ошибка при анализе. Попробуйте еще раз.";
  }
};

import React, { useState } from 'react';
import { 
  Calculator, 
  Percent, 
  Scale, 
  Briefcase, 
  Zap, 
  Settings as SettingsIcon, 
  ChevronLeft,
  Package,
  ArrowRight,
  RefreshCcw,
  Sparkles
} from 'lucide-react';
import { AppView, SettingsState } from './types';
import { Button } from './components/Button';
import { Input } from './components/Input';
import { analyzeShoppingDeal } from './services/geminiService';

// --- View Components ---

const MainMenu: React.FC<{ onViewSelect: (view: AppView) => void }> = ({ onViewSelect }) => {
  const menuItems = [
    { id: AppView.DISCOUNT_CALC, title: "Сколько стоит со скидкой", icon: <Package size={20} />, sub: "Цена - %" },
    { id: AppView.PROMO_CALC, title: "Скидка по акции N+X", icon: <Percent size={20} />, sub: "3 по цене 2 и др." },
    { id: AppView.UNIT_PRICE_CALC, title: "Сколько за кг/литр", icon: <Scale size={20} />, sub: "Сравнение упаковок" },
    { id: AppView.REVERSE_CALC, title: "Узнать регулярную цену", icon: <Briefcase size={20} />, sub: "Цена до скидки" },
    { id: AppView.PRO_MODE, title: "PRO режим", icon: <Sparkles size={20} className="text-yellow-400" />, sub: "Умный помощник AI", highlight: true },
    { id: AppView.SETTINGS, title: "Настройки", icon: <SettingsIcon size={20} />, sub: "Валюта и тема" },
  ];

  return (
    <div className="flex flex-col gap-3 p-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="bg-slate-800/50 p-4 rounded-xl mb-4 border border-slate-700/50 backdrop-blur-sm">
        <h1 className="text-xl font-bold flex items-center gap-2 mb-1">
          <span className="text-2xl">👋</span> Добро пожаловать!
        </h1>
        <p className="text-slate-400 text-sm">Выберите опцию для расчета:</p>
      </div>

      {menuItems.map((item) => (
        <button
          key={item.id}
          onClick={() => onViewSelect(item.id)}
          className={`group w-full p-4 rounded-xl flex items-center justify-between transition-all duration-200 border 
            ${item.highlight 
              ? 'bg-blue-900/30 border-blue-500/50 hover:bg-blue-900/50' 
              : 'bg-slate-800 border-slate-700 hover:bg-slate-700 hover:border-slate-600'
            } active:scale-[0.98] shadow-sm`}
        >
          <div className="flex items-center gap-4">
            <div className={`p-3 rounded-lg ${item.highlight ? 'bg-blue-600' : 'bg-slate-900'} text-white shadow-inner`}>
              {item.icon}
            </div>
            <div className="text-left">
              <div className="font-semibold text-base">{item.title}</div>
              <div className="text-xs text-slate-400">{item.sub}</div>
            </div>
          </div>
          <ArrowRight size={18} className="text-slate-500 group-hover:text-white transition-colors" />
        </button>
      ))}
    </div>
  );
};

const DiscountCalc: React.FC<{ currency: string }> = ({ currency }) => {
  const [price, setPrice] = useState<string>('');
  const [discount, setDiscount] = useState<string>('');

  const numPrice = parseFloat(price) || 0;
  const numDiscount = parseFloat(discount) || 0;
  const finalPrice = numPrice - (numPrice * (numDiscount / 100));
  const saved = numPrice - finalPrice;

  return (
    <div className="space-y-6">
      <div className="space-y-4">
        <Input 
          label="Цена товара" 
          type="number" 
          placeholder="0" 
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          suffix={currency}
          autoFocus
        />
        <Input 
          label="Скидка (%)" 
          type="number" 
          placeholder="0" 
          value={discount}
          onChange={(e) => setDiscount(e.target.value)}
          suffix="%"
        />
      </div>

      {price && (
        <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 space-y-4 shadow-lg">
          <div className="flex justify-between items-end pb-4 border-b border-slate-700">
            <span className="text-slate-400">Итоговая цена</span>
            <span className="text-3xl font-bold text-green-400">
              {finalPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
            </span>
          </div>
          <div className="flex justify-between items-center text-sm">
            <span className="text-slate-400">Вы экономите</span>
            <span className="font-semibold text-blue-400">
              {saved.toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

const PromoCalc: React.FC<{ currency: string }> = ({ currency }) => {
  const [price, setPrice] = useState<string>('');
  const [totalItems, setTotalItems] = useState<string>('3');
  const [paidItems, setPaidItems] = useState<string>('2');

  const numPrice = parseFloat(price) || 0;
  const n = parseFloat(totalItems) || 1;
  const x = parseFloat(paidItems) || 1;

  // Logic: "Buy N, pay for X"
  // Total cost = Price * X
  // Cost per item = (Price * X) / N
  // Effective Discount = (1 - (X/N)) * 100

  const totalCost = numPrice * x;
  const costPerItem = n > 0 ? totalCost / n : 0;
  const effectiveDiscount = n > 0 ? (1 - (x / n)) * 100 : 0;

  return (
    <div className="space-y-6">
      <Input 
        label="Цена за 1 шт (до акции)" 
        type="number" 
        value={price}
        onChange={(e) => setPrice(e.target.value)}
        suffix={currency}
      />

      <div className="grid grid-cols-2 gap-4">
        <Input 
          label="Берем (шт)" 
          type="number" 
          value={totalItems}
          onChange={(e) => setTotalItems(e.target.value)}
        />
        <Input 
          label="Платим за (шт)" 
          type="number" 
          value={paidItems}
          onChange={(e) => setPaidItems(e.target.value)}
        />
      </div>

      {price && (
        <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 space-y-3">
           <div className="flex justify-between items-center">
            <span className="text-slate-400">Цена за шт по акции</span>
            <span className="text-2xl font-bold text-white">
              {costPerItem.toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
            </span>
          </div>
          <div className="flex justify-between items-center text-sm">
            <span className="text-slate-400">Реальная скидка</span>
            <span className="font-semibold text-yellow-400">
              {effectiveDiscount.toFixed(1)}%
            </span>
          </div>
          <div className="mt-2 text-xs text-slate-500 text-center">
             Общая стоимость за {n} шт: {totalCost.toLocaleString()} {currency}
          </div>
        </div>
      )}
    </div>
  );
};

const UnitPriceCalc: React.FC<{ currency: string }> = ({ currency }) => {
  const [price, setPrice] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [unitType, setUnitType] = useState<'g' | 'kg' | 'ml' | 'l'>('g');

  const numPrice = parseFloat(price) || 0;
  const numWeight = parseFloat(weight) || 0;

  let factor = 1;
  let labelUnit = 'кг';

  if (unitType === 'g') { factor = 1000; labelUnit = 'кг'; }
  if (unitType === 'kg') { factor = 1; labelUnit = 'кг'; }
  if (unitType === 'ml') { factor = 1000; labelUnit = 'л'; }
  if (unitType === 'l') { factor = 1; labelUnit = 'л'; }

  const pricePerUnit = numWeight > 0 ? (numPrice / numWeight) * factor : 0;

  return (
    <div className="space-y-6">
       <Input 
          label="Цена товара" 
          type="number" 
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          suffix={currency}
        />

      <div className="flex gap-2 items-end">
        <div className="flex-1">
          <Input 
            label="Вес/Объем" 
            type="number" 
            value={weight}
            onChange={(e) => setWeight(e.target.value)}
          />
        </div>
        <div className="flex bg-slate-800 p-1 rounded-xl h-[50px] items-center border border-slate-700">
           {/* Simple toggle for units */}
           <select 
            value={unitType}
            onChange={(e) => setUnitType(e.target.value as any)}
            className="bg-transparent text-white text-sm font-medium focus:outline-none px-2 h-full"
           >
             <option value="g">грамм</option>
             <option value="kg">кг</option>
             <option value="ml">мл</option>
             <option value="l">литр</option>
           </select>
        </div>
      </div>

      {price && weight && (
        <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 text-center">
          <div className="text-slate-400 mb-1">Стоимость за 1 {labelUnit}</div>
          <div className="text-3xl font-bold text-blue-400">
            {pricePerUnit.toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
          </div>
        </div>
      )}
    </div>
  );
};

const ReverseCalc: React.FC<{ currency: string }> = ({ currency }) => {
  const [discountedPrice, setDiscountedPrice] = useState<string>('');
  const [percent, setPercent] = useState<string>('');

  const p = parseFloat(discountedPrice) || 0;
  const d = parseFloat(percent) || 0;

  // Original = Price / (1 - discount/100)
  const original = (d > 0 && d < 100) ? p / (1 - (d/100)) : 0;

  return (
    <div className="space-y-6">
       <div className="bg-blue-900/20 p-4 rounded-xl text-sm text-blue-200 mb-4 border border-blue-900/50">
         Полезно, когда вы видите только финальную цену и процент скидки, но хотите узнать, сколько товар стоил раньше.
       </div>

       <Input 
          label="Цена со скидкой" 
          type="number" 
          value={discountedPrice}
          onChange={(e) => setDiscountedPrice(e.target.value)}
          suffix={currency}
        />
        <Input 
          label="Процент скидки" 
          type="number" 
          value={percent}
          onChange={(e) => setPercent(e.target.value)}
          suffix="%"
        />

      {original > 0 && (
         <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 space-y-2">
            <div className="flex justify-between items-center">
              <span className="text-slate-400">Регулярная цена</span>
              <span className="text-xl font-bold line-through text-slate-500">
                {original.toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
              </span>
            </div>
            <div className="flex justify-between items-center pt-2 border-t border-slate-700 mt-2">
               <span className="text-slate-400">Вы сэкономили</span>
               <span className="text-green-400 font-semibold">
                  {(original - p).toLocaleString(undefined, { maximumFractionDigits: 2 })} {currency}
               </span>
            </div>
         </div>
      )}
    </div>
  );
};

const ProMode: React.FC<{ currency: string }> = ({ currency }) => {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const handleAsk = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setResult(null);
    const response = await analyzeShoppingDeal(query, currency);
    setResult(response);
    setLoading(false);
  };

  return (
    <div className="space-y-4 h-full flex flex-col">
      <div className="bg-gradient-to-r from-purple-900/40 to-blue-900/40 p-4 rounded-xl border border-white/10 mb-2">
        <h3 className="font-bold flex items-center gap-2 text-purple-200">
          <Sparkles size={18} /> Умный помощник
        </h3>
        <p className="text-xs text-purple-200/70 mt-1">
          Спросите что угодно. Например: "Что выгоднее: 300г сыра за 500р или 450г за 700р?"
        </p>
      </div>

      <div className="flex-1 overflow-y-auto">
        {result && (
          <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 animate-in fade-in zoom-in-95 duration-300">
            <div className="prose prose-invert prose-sm whitespace-pre-wrap">
              {result}
            </div>
          </div>
        )}
      </div>

      <div className="mt-auto pt-4">
        <textarea 
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Опишите ситуацию..."
          className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-white focus:outline-none focus:border-purple-500 min-h-[80px] mb-3 resize-none"
        />
        <Button 
          fullWidth 
          onClick={handleAsk} 
          disabled={loading || !query.trim()}
          className="bg-gradient-to-r from-blue-600 to-purple-600 border-none"
        >
          {loading ? (
             <span className="flex items-center gap-2">
               <RefreshCcw className="animate-spin" size={18} /> Думаю...
             </span>
          ) : (
            'Рассчитать выгоду'
          )}
        </Button>
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.MAIN_MENU);
  const [settings, setSettings] = useState<SettingsState>({ currency: '₽' });

  // Function to render the specific header based on view
  const getHeaderTitle = () => {
    switch (currentView) {
      case AppView.DISCOUNT_CALC: return "Калькулятор скидки";
      case AppView.PROMO_CALC: return "Акция N+X";
      case AppView.UNIT_PRICE_CALC: return "Цена за КГ/Литр";
      case AppView.REVERSE_CALC: return "Поиск цены без скидки";
      case AppView.PRO_MODE: return "PRO Режим";
      case AppView.SETTINGS: return "Настройки";
      default: return "";
    }
  };

  const handleBack = () => setCurrentView(AppView.MAIN_MENU);

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex justify-center">
      <div className="w-full max-w-md flex flex-col h-screen">

        {/* Header */}
        {currentView !== AppView.MAIN_MENU && (
          <div className="sticky top-0 z-10 bg-slate-900/95 backdrop-blur-md border-b border-slate-800 p-4 flex items-center gap-4">
            <button 
              onClick={handleBack}
              className="p-2 -ml-2 hover:bg-slate-800 rounded-full transition-colors"
            >
              <ChevronLeft size={24} />
            </button>
            <h2 className="font-bold text-lg">{getHeaderTitle()}</h2>
          </div>
        )}

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 scroll-smooth">
          {currentView === AppView.MAIN_MENU && (
            <MainMenu onViewSelect={setCurrentView} />
          )}

          {currentView === AppView.DISCOUNT_CALC && (
            <div className="animate-in slide-in-from-right-8 duration-300">
               <DiscountCalc currency={settings.currency} />
            </div>
          )}

          {currentView === AppView.PROMO_CALC && (
            <div className="animate-in slide-in-from-right-8 duration-300">
               <PromoCalc currency={settings.currency} />
            </div>
          )}

          {currentView === AppView.UNIT_PRICE_CALC && (
            <div className="animate-in slide-in-from-right-8 duration-300">
               <UnitPriceCalc currency={settings.currency} />
            </div>
          )}

          {currentView === AppView.REVERSE_CALC && (
            <div className="animate-in slide-in-from-right-8 duration-300">
               <ReverseCalc currency={settings.currency} />
            </div>
          )}

          {currentView === AppView.PRO_MODE && (
            <div className="animate-in slide-in-from-right-8 duration-300 h-full">
               <ProMode currency={settings.currency} />
            </div>
          )}

          {currentView === AppView.SETTINGS && (
            <div className="animate-in slide-in-from-right-8 duration-300 space-y-6">
               <div>
                  <label className="block text-sm font-medium text-slate-400 mb-2">Валюта</label>
                  <div className="grid grid-cols-4 gap-2">
                    {['₽', '$', '€', '₸'].map(cur => (
                      <button
                        key={cur}
                        onClick={() => setSettings(s => ({ ...s, currency: cur }))}
                        className={`p-3 rounded-xl border ${
                          settings.currency === cur 
                          ? 'bg-blue-600 border-blue-500 text-white' 
                          : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                        }`}
                      >
                        {cur}
                      </button>
                    ))}
                  </div>
               </div>
               <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 text-sm text-slate-400 text-center">
                 Версия приложения 1.0.0
               </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

