import React from 'react';

interface InputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange'> {
  label: string;
  suffix?: string;
  isActive?: boolean;
  onInputClick?: () => void;
  value: string;
}

export const Input: React.FC<InputProps> = ({ 
  label, 
  suffix, 
