            isActive={activeField === 'price'}
            onInputClick={() => setActiveField('price')}
            suffix={currency}
          />

        <div className="flex gap-2 items-end">
          <div className="flex-1">
            <Input 
              label={t.unitPriceCalc.weightLabel}
              value={values.weight}
              isActive={activeField === 'weight'}
