      priceLabel: "Base Price",
      buyLabel: "Buy (N)",
      freeLabel: "Get Free (X)",
      targetLabel: "Target Total",
      pricePerItem: "Promo Price per 1",
      realDiscount: "Real Discount",
      totalCost: "Total Cost",
      toInvoice: "To Invoice (Pay)",
      toAdd: "Bonus (Free)",
      item: "pcs",
      emptyState: "Enter price & conditions"
